// correlationCache keeps the result until the data or the day changes.
type correlationCache struct {
	mu   sync.Mutex
	key  string
	view *correlationsView
}

type correlationFinding struct {
	Text   string
	Detail string
}

// correlationsView is the "Was dich beeinflusst" section of the health page.
type correlationsView struct {
	Findings []correlationFinding
	// NoEffect and TooFew list the labels of the other tested pairs.
	NoEffect string
	TooFew   string
}

var correlationColumns = []string{insight.HRV, insight.RestingHR, insight.Sleep, insight.SleepScr, insight.BodyHigh, insight.Stress}

func (s *server) correlations(ctx context.Context, today time.Time) (*correlationsView, error) {
	count, err := s.Store.Count(ctx)
	if err != nil {
		return nil, err
	}
	days, err := s.Store.HealthDayCount(ctx)
	if err != nil {
		return nil, err
	}
	last, _, err := s.Store.LatestHealthDate(ctx)
	if err != nil {
		return nil, err
	}
	key := fmt.Sprintf("%s/%d/%d/%s", today.Format(time.DateOnly), count, days, last.Format(time.DateOnly))
	c := &s.correlationCache
	c.mu.Lock()
	defer c.mu.Unlock()
	if c.key == key {
		return c.view, nil
	}
	series, err := s.correlationSeries(ctx, today)
	if err != nil {
		return nil, err
	}
	c.key, c.view = key, newCorrelationsView(insight.CorrelateAll(series))
	return c.view, nil
}

// correlationSeries builds the daily series: health values (daily totals
// only for complete days), the Garmin load and minutes in HR zones 4–5,
// both 0 on days without activities.
func (s *server) correlationSeries(ctx context.Context, today time.Time) (insight.Series, error) {
	series := insight.Series{}
	put := func(metric string, day time.Time, v float64) {
		if series[metric] == nil {
			series[metric] = map[time.Time]float64{}
		}
		series[metric][day] = v
	}
	health, err := s.Store.HealthDays(ctx, time.Unix(0, 0).UTC(), today, correlationColumns)
	if err != nil {
		return nil, err
	}
	var first, last time.Time
	for _, d := range health {
		for col, v := range d.Values {
			f, ok := num(v)
			if !ok || (insight.DailyTotals[col] && !d.Date.Before(today)) {
				continue
			}
			put(col, d.Date, f)
		}
		if first.IsZero() {
			first = d.Date
		}
		last = d.Date
	}
	if first.IsZero() {
		return series, nil
	}
	start, ok, err := s.Store.FirstLocalStart(ctx)
	if err != nil || !ok {
		return series, err
	}
	if from := localDate(start); from.After(first) {
		first = from
	}
	loads, err := s.Store.DailyLoad(ctx, first, last.AddDate(0, 0, 1))
	if err != nil {
		return nil, err
	}
	zones, err := s.Store.ZoneTotals(ctx, store.ListFilter{From: first, To: last.AddDate(0, 0, 1)}, store.ZoneHR, store.ByDay)
	if err != nil {
		return nil, err
	}
	for d := first; !d.After(last); d = d.AddDate(0, 0, 1) {
		put(insight.Load, d, 0)
		put(insight.HardMin, d, 0)
	}
	for _, l := range loads {
		put(insight.Load, l.Date, l.Garmin)
	}
	for _, z := range zones {
		if d, err := time.Parse(time.DateOnly, z.Key); err == nil && z.Zone >= 4 {
			series[insight.HardMin][d] += z.Seconds / 60
		}
	}
	return series, nil
}

func newCorrelationsView(cs []insight.Correlation) *correlationsView {
	v := &correlationsView{}
	var none, few []string
	for _, c := range cs {
		switch {
		case !c.EnoughData:
			few = append(few, c.TestedLabel)
		case c.Significant:
			v.Findings = append(v.Findings, correlationFinding{Text: c.Text, Detail: correlationDetail(c)})
		default:
			none = append(none, c.TestedLabel)
		}
	}
	v.NoEffect, v.TooFew = strings.Join(none, ", "), strings.Join(few, ", ")
	if len(v.Findings) == 0 && v.NoEffect == "" {
		return nil
	}
	return v
}

func correlationDetail(c insight.Correlation) string {
	lo, hi := math.Abs(c.CILow), math.Abs(c.CIHi)
	if lo > hi {
		lo, hi = hi, lo
	}
	p := "p < 0,001"
	if c.P >= 0.001 {
		p = "p = " + germanFloat(c.P, 3)
	}
	rho := strings.NewReplacer(".", ",", "-", "−").Replace(fmt.Sprintf("%+.2f", c.Rho))
	return fmt.Sprintf("95-%%-Intervall %s–%s %s · %s · Rangkorrelation %s", germanFloat(lo, 1), germanFloat(hi, 1), c.Unit, p, rho)
}
